#!/usr/bin/env bash
# test-gemini-hooks.sh — the Gemini CLI hook layer: generator, wrapper, policies.
#
# WHAT THIS PINS
#   platforms/gemini/hooks.json and platforms/gemini/policies/tamirs-superpowers.toml
#   are generated by scripts/build-gemini-hooks.sh from hooks/hooks.json and
#   platforms/gemini/policies.source.json; hooks/gemini-wrap.sh is what every
#   generated command runs. Three things can rot:
#     - the generated files drift from their sources (hand edit, or a canonical
#       change without a regenerate) — so planted drift MUST fail --check;
#     - the generated file carries something Gemini cannot run (a Claude event,
#       a Claude tool name, `${CLAUDE_PLUGIN_ROOT}`, `onFailure`, a timeout in
#       seconds) — so the shape is asserted field by field;
#     - the wrapper's two translations silently stop matching the canonical
#       hooks' dialect — so a real guard is run on a real Gemini-shaped payload
#       and its decision read back, plus synthetic hooks for every envelope.
#
# Runs without a Gemini binary. Needs jq, git and python3 >= 3.11 (tomllib).
# Exit 0 if all pass, 1 otherwise.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=tests/lib/harness.sh
source "$ROOT/tests/lib/harness.sh"

harness_require jq git python3
python3 -c 'import tomllib' >/dev/null 2>&1 || { echo "FATAL: python3 >= 3.11 (tomllib) is required"; exit 1; }

GEN="$ROOT/scripts/build-gemini-hooks.sh"
WRAP="$ROOT/hooks/gemini-wrap.sh"
HOOKS="$ROOT/platforms/gemini/hooks.json"
POLICY="$ROOT/platforms/gemini/policies/tamirs-superpowers.toml"
[ -f "$GEN" ] || { echo "FATAL: generator not found at $GEN"; exit 1; }
[ -f "$WRAP" ] || { echo "FATAL: wrapper not found at $WRAP"; exit 1; }

TMP="$(harness_tmpdir)"
export HOME="$TMP/home"
mkdir -p "$HOME/.claude"

# assert_exit <name> <expected-code> <command...>
assert_exit() {
  local name="$1" want="$2"; shift 2
  local out got
  out=$("$@" 2>&1); got=$?
  if [ "$got" -eq "$want" ]; then ok "$name"; else bad "$name" "expected exit $want, got $got: ${out:0:300}"; fi
}

# A scratch copy of what the generator reads: the canonical hooks file, every
# hook script it names (existence is checked), the wrapper, the policy source
# and the committed outputs. Generators take the root as an argument.
make_copy() {
  local dst="$1"
  mkdir -p "$dst/platforms/gemini" "$dst/scripts"
  cp -R "$ROOT/hooks" "$dst/hooks"
  cp "$ROOT/scripts/notify-pushover.sh" "$dst/scripts/notify-pushover.sh"
  cp "$ROOT/platforms/gemini/policies.source.json" "$dst/platforms/gemini/"
  cp "$HOOKS" "$dst/platforms/gemini/hooks.json"
  mkdir -p "$dst/platforms/gemini/policies"
  cp "$POLICY" "$dst/platforms/gemini/policies/"
}

# edit_json <file> <jq-filter>
edit_json() { local f="$1" q="$2"; jq "$q" "$f" > "$f.tmp" && mv "$f.tmp" "$f"; }

section "generator: --check passes on the committed tree"
assert_exit "build-gemini-hooks.sh --check passes" 0 bash "$GEN" "$ROOT" --check
assert_exit "--help exits 0" 0 bash "$GEN" --help
assert_exit "an unknown flag is rejected" 1 bash "$GEN" "$ROOT" --bogus

section "generator: planted drift fails --check (scratch copy)"
C="$TMP/drift-out"; make_copy "$C"
edit_json "$C/platforms/gemini/hooks.json" '.hooks.BeforeTool[0].hooks[0].timeout = 1'
assert_exit "a hand-edited platforms/gemini/hooks.json fails --check" 1 bash "$GEN" "$C" --check

C="$TMP/drift-src"; make_copy "$C"
edit_json "$C/hooks/hooks.json" '.hooks.SessionEnd[0].hooks[0].timeout = 31'
assert_exit "an edited hooks/hooks.json without a regenerate fails --check" 1 bash "$GEN" "$C" --check

C="$TMP/drift-policy"; make_copy "$C"
edit_json "$C/platforms/gemini/policies.source.json" '.rules[0].denyMessage = "changed"'
assert_exit "an edited policies.source.json without a regenerate fails --check" 1 bash "$GEN" "$C" --check

C="$TMP/drift-missing"; make_copy "$C"
rm -f "$C/platforms/gemini/hooks.json"
assert_exit "a missing generated hooks file fails --check" 1 bash "$GEN" "$C" --check

C="$TMP/regen"; make_copy "$C"
edit_json "$C/hooks/hooks.json" '.hooks.SessionEnd[0].hooks[0].timeout = 31'
assert_exit "a normal run after the edit succeeds" 0 bash "$GEN" "$C"
assert_exit "...and --check passes again" 0 bash "$GEN" "$C" --check
judge "the regenerated timeout is in milliseconds (31s -> 31000)" 31000 \
  "$(jq '.hooks.SessionEnd[0].hooks[0].timeout' "$C/platforms/gemini/hooks.json")"

section "generator: a source it cannot translate is an error, never a silent drop"
C="$TMP/bad-event"; make_copy "$C"
edit_json "$C/hooks/hooks.json" '.hooks.PermissionRequest = [{"hooks":[{"type":"command","command":"bash \"${CLAUDE_PLUGIN_ROOT}\"/hooks/check-done.sh"}]}]'
assert_exit "an event with no Gemini mapping and not on the dropped list is exit 2" 2 bash "$GEN" "$C"

C="$TMP/bad-matcher"; make_copy "$C"
edit_json "$C/hooks/hooks.json" '.hooks.PreToolUse[0].matcher = "Bash|WebFetch"'
assert_exit "a matcher token with no Gemini tool name is exit 2" 2 bash "$GEN" "$C"

C="$TMP/bad-script"; make_copy "$C"
edit_json "$C/hooks/hooks.json" '.hooks.Stop[0].hooks[0].command = "bash \"${CLAUDE_PLUGIN_ROOT}\"/hooks/does-not-exist.sh"'
assert_exit "a command naming a missing script is exit 2" 2 bash "$GEN" "$C"

C="$TMP/bad-key"; make_copy "$C"
edit_json "$C/hooks/hooks.json" '.hooks.Stop[0].hooks[0].newClaudeField = true'
assert_exit "an unknown per-hook key is exit 2" 2 bash "$GEN" "$C"

C="$TMP/bad-decision"; make_copy "$C"
edit_json "$C/platforms/gemini/policies.source.json" '.rules[0].decision = "allow"'
assert_exit "a policy rule with decision allow is exit 2" 2 bash "$GEN" "$C"

C="$TMP/bad-regex"; make_copy "$C"
edit_json "$C/platforms/gemini/policies.source.json" '.rules[0].commandRegex = "git push ("'
assert_exit "a policy regex that does not compile is exit 2" 2 bash "$GEN" "$C"

C="$TMP/no-wrapper"; make_copy "$C"
rm -f "$C/hooks/gemini-wrap.sh"
assert_exit "a missing gemini-wrap.sh is exit 2" 2 bash "$GEN" "$C"

section "generated hooks file: only what Gemini can run"
GEMINI_EVENTS='BeforeTool AfterTool BeforeAgent AfterAgent BeforeModel AfterModel BeforeToolSelection SessionStart SessionEnd Notification PreCompress'
bad_events=""
while IFS= read -r ev; do
  case " $GEMINI_EVENTS " in *" $ev "*) ;; *) bad_events="$bad_events $ev" ;; esac
done < <(jq -r '.hooks | keys[]' "$HOOKS")
judge "every event is a Gemini event" "" "$bad_events"
judge "no modules key" "no" "$(if jq -e 'has("modules")' "$HOOKS" >/dev/null; then echo yes; else echo no; fi)"
judge "the mapped events are present" "AfterAgent AfterTool BeforeAgent BeforeTool Notification PreCompress SessionEnd SessionStart" \
  "$(jq -r '.hooks | keys | sort | join(" ")' "$HOOKS")"
judge "no onFailure survives on any hook" 0 "$(jq '[.hooks[][].hooks[] | select(has("onFailure"))] | length' "$HOOKS")"
judge "no statusMessage survives (it became description)" 0 "$(jq '[.hooks[][].hooks[] | select(has("statusMessage"))] | length' "$HOOKS")"
judge "only Gemini hook fields are emitted" "" "$(jq -r '.hooks[][].hooks[] | keys[] | select(IN("name","type","command","timeout","description") | not)' "$HOOKS" | sort -u)"
judge "no CLAUDE_PLUGIN_ROOT survives" 0 "$(grep -c 'CLAUDE_PLUGIN_ROOT' "$HOOKS")"
judge "no Claude tool name survives in a matcher" "" \
  "$(jq -r '.hooks[][] | .matcher // empty' "$HOOKS" | grep -E 'Bash|Edit|Write|Shell|Notebook|StrReplace' || true)"
judge "every tool matcher is anchored" "" \
  "$(jq -r '(.hooks.BeforeTool + .hooks.AfterTool)[] | .matcher // empty' "$HOOKS" | grep -vE '^\^\(.*\)\$$' || true)"
judge "tool matchers name only write_file/replace/run_shell_command" "" \
  "$(jq -r '(.hooks.BeforeTool + .hooks.AfterTool)[] | .matcher // empty' "$HOOKS" | sed 's/[\^()$]//g' | tr '|' '\n' | sort -u | grep -vE '^(write_file|replace|run_shell_command)$' || true)"
judge "lifecycle groups carry no matcher (Gemini compares those as exact strings)" "" \
  "$(jq -r '(.hooks.AfterAgent + .hooks.BeforeAgent + .hooks.SessionStart + .hooks.SessionEnd + .hooks.Notification + .hooks.PreCompress)[] | .matcher // empty' "$HOOKS")"

missing_scripts=""; not_wrapped=""; bad_timeout=""
while IFS= read -r cmd; do
  case "$cmd" in
    'bash "${extensionPath}/hooks/gemini-wrap.sh" "${extensionPath}/'*) ;;
    *) not_wrapped="$not_wrapped | $cmd" ;;
  esac
  rel="${cmd##*gemini-wrap.sh\" \"\$\{extensionPath\}/}"; rel="${rel%\"}"
  [ -f "$ROOT/$rel" ] || missing_scripts="$missing_scripts $rel"
done < <(jq -r '.hooks[][].hooks[].command' "$HOOKS")
judge "every command runs the canonical hook through gemini-wrap.sh" "" "$not_wrapped"
judge "every command names a script that exists" "" "$missing_scripts"
while IFS= read -r t; do
  [ "$t" = null ] && continue
  { [ "$t" -ge 1000 ] 2>/dev/null && [ $((t % 1000)) -eq 0 ]; } || bad_timeout="$bad_timeout $t"
done < <(jq -r '.hooks[][].hooks[].timeout' "$HOOKS")
judge "every timeout is a whole number of seconds expressed in milliseconds" "" "$bad_timeout"
judge "every hook has a name" 0 "$(jq '[.hooks[][].hooks[] | select(.name == null or .name == "")] | length' "$HOOKS")"
judge "hook names are unique" "" "$(jq -r '.hooks[][].hooks[].name' "$HOOKS" | sort | uniq -d)"
judge "every hook is type command" 0 "$(jq '[.hooks[][].hooks[] | select(.type != "command")] | length' "$HOOKS")"
n_canon="$(jq '[.hooks | to_entries[] | select(.key | IN("WorktreeCreate","WorktreeRemove","DirectoryAdded","StopFailure","SubagentStop","TaskCompleted","TeammateIdle") | not) | .value[].hooks[]] | length' "$ROOT/hooks/hooks.json")"
n_gem="$(jq '[.hooks[][].hooks[]] | length' "$HOOKS")"
judge "every canonical hook outside the dropped events is carried over ($n_canon)" "$n_canon" "$n_gem"

section "policies: TOML parses, every rule denies, every regex does what its name says"
policy_check="$(python3 -I - "$POLICY" <<'PY' 2>&1
import re, sys, tomllib, json
d = tomllib.load(open(sys.argv[1], "rb"))
rules = d.get("rule", [])
assert rules, "no [[rule]] blocks"
assert "safety_checker" not in d, "unexpected [[safety_checker]]"
for r in rules:
    assert r["decision"] == "deny", "rule %r is not a deny" % r
    assert isinstance(r["priority"], int) and 0 <= r["priority"] <= 999, r
    assert r.get("denyMessage", "").strip(), "rule without denyMessage: %r" % r
    assert ("commandRegex" in r) != ("argsPattern" in r), r
    re.compile(r.get("commandRegex") or r.get("argsPattern"))
cmd = {r["commandRegex"] for r in rules if "commandRegex" in r}
args = {r["argsPattern"] for r in rules if "argsPattern" in r}
def any_match(pats, s): return any(re.search(p, s) for p in pats)
# commandRegex samples
for s in ("git push --force origin main", "git push -f", "cd x && git push origin -f feature", "git branch -D topic",
          "git branch -rD origin/topic", "git branch --delete --force topic"):
    assert any_match(cmd, s), "should deny: %r" % s
for s in ("git push --force-with-lease origin feature", "git push origin main", "git branch -d topic",
          "git branch -a", "git log --format=%f", "echo git push --force"):
    # `echo git push --force` IS matched by \bgit\s+push: a false positive the
    # hook layer also accepts; it is listed here to make the trade-off visible.
    if s.startswith("echo"):
        assert any_match(cmd, s); continue
    assert not any_match(cmd, s), "should allow: %r" % s
# argsPattern samples, over JSON.stringify(tool_input) as Gemini evaluates them
def args_json(p): return json.dumps({"file_path": p, "content": "x"}, separators=(",", ":"))
for p in ("/r/package-lock.json", "/r/sub/yarn.lock", "/r/Cargo.lock", "/r/pnpm-lock.yaml", "/r/bun.lockb",
          "/r/go.sum", "/r/.yarn/releases/yarn-4.1.0.cjs", "/r/.github/workflows/ci.yml"):
    assert any_match(args, args_json(p)), "should deny: %r" % p
for p in ("/r/src/app.ts", "/r/package.json", "/r/go.mod", "/r/.github/CODEOWNERS", "/r/docs/lockfiles.md",
          "/r/.github/workflows", "/r/notes/go.summary"):
    assert not any_match(args, args_json(p)), "should allow: %r" % p
print("ok %d rules" % len(rules))
PY
)"
judge "policy TOML parses, every rule denies, regex samples behave" "ok 5 rules" "$policy_check"
judge "policies.source.json names what is NOT expressible" yes \
  "$(if [ "$(jq '.not_expressible | length' "$ROOT/platforms/gemini/policies.source.json")" -gt 0 ]; then echo yes; else echo no; fi)"

section "wrapper: a real guard on a real Gemini payload"
new_repo() {
  local dir="$1"
  mkdir -p "$dir"
  git -C "$dir" init -q -b main
  git -C "$dir" config user.email t@e
  git -C "$dir" config user.name t
  git -C "$dir" commit -q --allow-empty -m init
}
E="$TMP/repo"; new_repo "$E"
mkdir -p "$E/.dev-files/objectives/auth"
jq -n '{id:"auth", status:"active"}' > "$E/.dev-files/objectives/auth/objective.json"
git -C "$E" worktree add -q -B worker/auth/001 "$E/.agent-worktrees/auth/task-001" main 2>/dev/null

# run_wrap <hook> <payload-json> — stdout of the wrapper (stderr discarded)
run_wrap() { printf '%s' "$2" | bash "$WRAP" "$ROOT/hooks/$1" 2>/dev/null; }
gpayload() { # gpayload <tool> <file> <cwd>
  jq -n --arg t "$1" --arg f "$2" --arg cwd "$3" \
    '{session_id:"s", transcript_path:"/t", cwd:$cwd, hook_event_name:"BeforeTool", timestamp:"now",
      tool_name:$t, tool_input:{file_path:$f, content:"x"}}'
}

out="$(run_wrap enforce-worktree-edits.sh "$(gpayload write_file "$E/src/app.ts" "$E")")"
judge "write_file into the main checkout under an active objective is denied" deny "$(jq -r '.decision // "allow"' <<<"$out")"
judge "the deny carries the objective's remedy" yes "$(has "$out" ".agent-worktrees/auth/task-NNN")"
judge "stdout is exactly one line" 1 "$(printf '%s\n' "$out" | wc -l | tr -d ' ')"
judge "stdout is one JSON object" object "$(jq -r type <<<"$out" 2>/dev/null)"
out="$(run_wrap enforce-worktree-edits.sh "$(gpayload replace "$E/.agent-worktrees/auth/task-001/src/app.ts" "$E")")"
judge "replace inside the worker worktree is allowed with {}" "{}" "$out"
out="$(run_wrap enforce-worktree-edits.sh "$(gpayload read_file "$E/src/app.ts" "$E")")"
judge "an unmapped tool (read_file) passes through and is allowed" "{}" "$out"

sh_payload="$(jq -n --arg cwd "$E" '{session_id:"s", cwd:$cwd, hook_event_name:"BeforeTool", tool_name:"run_shell_command",
  tool_input:{command:"echo x > package-lock.json", dir_path:"."}}')"
out="$(run_wrap guard-sensitive-files.sh "$sh_payload")"
judge "run_shell_command writing a lockfile is denied by guard-sensitive-files" deny "$(jq -r '.decision // "allow"' <<<"$out")"
sh_payload="$(jq -n --arg cwd "$E" '{session_id:"s", cwd:$cwd, hook_event_name:"BeforeTool", tool_name:"run_shell_command",
  tool_input:{command:"echo hello"}}')"
judge "a harmless run_shell_command is allowed" "{}" "$(run_wrap guard-sensitive-files.sh "$sh_payload")"

section "wrapper: payload translation"
# shellcheck source=hooks/lib/gemini-output.sh
source "$ROOT/hooks/lib/gemini-output.sh"
t="$(gemini_translate_input "$(jq -n '{hook_event_name:"BeforeTool", tool_name:"write_file", tool_input:{file_path:"/a/b", content:"c"}, cwd:"/w"}')")"
judge "write_file -> Write" Write "$(jq -r .tool_name <<<"$t")"
judge "BeforeTool -> PreToolUse" PreToolUse "$(jq -r .hook_event_name <<<"$t")"
judge "file_path is preserved" /a/b "$(jq -r .tool_input.file_path <<<"$t")"
judge "the original Gemini tool name is kept beside it" write_file "$(jq -r .gemini_tool_name <<<"$t")"
t="$(gemini_translate_input "$(jq -n '{hook_event_name:"AfterTool", tool_name:"replace", tool_input:{file_path:"/a", old_string:"x", new_string:"y"}}')")"
judge "replace -> Edit, AfterTool -> PostToolUse" "Edit PostToolUse" "$(jq -r '"\(.tool_name) \(.hook_event_name)"' <<<"$t")"
t="$(gemini_translate_input "$(jq -n '{tool_name:"run_shell_command", tool_input:{command:"ls", dir_path:"sub/dir"}, cwd:"/w"}')")"
judge "run_shell_command -> Bash" Bash "$(jq -r .tool_name <<<"$t")"
judge "a relative dir_path becomes cwd resolved against the session cwd" /w/sub/dir "$(jq -r .cwd <<<"$t")"
t="$(gemini_translate_input "$(jq -n '{tool_name:"run_shell_command", tool_input:{command:"ls", dir_path:"/abs"}, cwd:"/w"}')")"
judge "an absolute dir_path becomes cwd as-is" /abs "$(jq -r .cwd <<<"$t")"
t="$(GEMINI_CWD=/from-env gemini_translate_input "$(jq -n '{tool_name:"read_file"}')")"
judge "a missing cwd falls back to GEMINI_CWD" /from-env "$(jq -r .cwd <<<"$t")"
for pair in "BeforeAgent UserPromptSubmit" "AfterAgent Stop" "PreCompress PreCompact" "SessionStart SessionStart" "Notification Notification"; do
  set -- $pair
  judge "$1 -> $2" "$2" "$(gemini_translate_input "$(jq -n --arg e "$1" '{hook_event_name:$e}')" | jq -r .hook_event_name)"
done
judge "gemini_is_gemini: GEMINI_SESSION_ID in the environment" 0 "$(GEMINI_SESSION_ID=x gemini_is_gemini '{}'; echo $?)"
judge "gemini_is_gemini: a Gemini-only event name in the payload" 0 "$(gemini_is_gemini '{"hook_event_name":"BeforeTool"}'; echo $?)"
judge "gemini_is_gemini: a Claude payload with no Gemini env is not Gemini" 1 "$(gemini_is_gemini '{"hook_event_name":"PreToolUse"}'; echo $?)"

section "wrapper: answer translation, one synthetic hook per envelope"
FAKE="$TMP/fake"; mkdir -p "$FAKE"
mk() { printf '#!/usr/bin/env bash\ncat >/dev/null\n%s\n' "$2" > "$FAKE/$1"; }
mk deny.sh   "printf '%s\n' '{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"deny\",\"permissionDecisionReason\":\"no\"}}'"
mk ask.sh    "printf '%s\n' '{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"ask\",\"permissionDecisionReason\":\"sure?\"}}'"
mk block.sh  "printf '%s\n' '{\"decision\":\"block\",\"reason\":\"keep going\"}'"
mk ctx.sh    "printf '%s\n' '{\"hookSpecificOutput\":{\"hookEventName\":\"UserPromptSubmit\",\"additionalContext\":\"hint\"}}'"
mk ctx2.sh   "printf '%s\n' '{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"additionalContext\":\"note\"},\"systemMessage\":\"note\"}'"
mk sys.sh    "printf '%s\n' '{\"suppressOutput\":true,\"systemMessage\":\"hello\"}'"
mk text.sh   "echo 'plain text, not json'"
mk empty.sh  ":"
mk exit2.sh  "echo 'blocked on stderr' >&2; exit 2"
mk exit3.sh  "echo 'oops' >&2; exit 3"
mk upd.sh    "printf '%s\n' '{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"updatedInput\":{\"file_path\":\"/new\"}}}'"
wrapf() { printf '%s' "$2" | bash "$WRAP" "$FAKE/$1" 2>"$TMP/err.txt"; }
P_TOOL='{"hook_event_name":"BeforeTool","tool_name":"write_file","tool_input":{"file_path":"/x"}}'
P_AFTER='{"hook_event_name":"AfterTool","tool_name":"write_file","tool_input":{"file_path":"/x"},"tool_response":{}}'
P_AGENT='{"hook_event_name":"BeforeAgent","prompt":"p"}'
P_STOP='{"hook_event_name":"AfterAgent","prompt":"p","prompt_response":"r","stop_hook_active":false}'
P_START='{"hook_event_name":"SessionStart","source":"startup"}'
judge "permissionDecision deny -> decision deny + reason" '{"decision":"deny","reason":"no"}' "$(wrapf deny.sh "$P_TOOL")"
judge "permissionDecision ask -> decision ask" '{"decision":"ask","reason":"sure?"}' "$(wrapf ask.sh "$P_TOOL")"
judge "Stop decision block -> AfterAgent deny with the reason" '{"decision":"deny","reason":"keep going"}' "$(wrapf block.sh "$P_STOP")"
judge "additionalContext on BeforeAgent -> hookSpecificOutput with its hookEventName" \
  '{"hookSpecificOutput":{"hookEventName":"BeforeAgent","additionalContext":"hint"}}' "$(wrapf ctx.sh "$P_AGENT")"
judge "additionalContext on AfterTool -> hookSpecificOutput.additionalContext" \
  '{"hookSpecificOutput":{"hookEventName":"AfterTool","additionalContext":"hint"}}' "$(wrapf ctx.sh "$P_AFTER")"
judge "additionalContext on SessionStart -> hookSpecificOutput.additionalContext" \
  '{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"hint"}}' "$(wrapf ctx.sh "$P_START")"
judge "additionalContext on BeforeTool -> systemMessage, not doubled when the hook sent both (hook_additional_context does)" \
  '{"systemMessage":"note"}' "$(wrapf ctx2.sh "$P_TOOL")"
mk ctx3.sh   "printf '%s\n' '{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"additionalContext\":\"b\"},\"systemMessage\":\"a\"}'"
judge "...and joined on a newline when they differ" '{"systemMessage":"a\nb"}' "$(wrapf ctx3.sh "$P_TOOL")"
judge "systemMessage and suppressOutput pass through" '{"systemMessage":"hello","suppressOutput":true}' "$(wrapf sys.sh "$P_START")"
judge "updatedInput on BeforeTool -> hookSpecificOutput.tool_input" \
  '{"hookSpecificOutput":{"hookEventName":"BeforeTool","tool_input":{"file_path":"/new"}}}' "$(wrapf upd.sh "$P_TOOL")"
judge "plain-text stdout becomes {} (text forwarded to stderr)" "{}" "$(wrapf text.sh "$P_TOOL")"
judge "...and the text reached stderr" yes "$(has "$(cat "$TMP/err.txt")" "plain text, not json")"
judge "empty stdout becomes {}" "{}" "$(wrapf empty.sh "$P_TOOL")"
judge "exit 2 becomes decision deny with stderr as the reason" '{"decision":"deny","reason":"blocked on stderr"}' "$(wrapf exit2.sh "$P_TOOL")"
judge "any other non-zero exit becomes {} (Claude: non-blocking error)" "{}" "$(wrapf exit3.sh "$P_TOOL")"
judge "...with the wrapper's own exit 0" 0 "$(printf '%s' "$P_TOOL" | bash "$WRAP" "$FAKE/exit3.sh" >/dev/null 2>&1; echo $?)"
judge "a missing hook script answers {}" "{}" "$(printf '%s' "$P_TOOL" | bash "$WRAP" "$FAKE/nope.sh" 2>/dev/null)"
judge "...and exits 0" 0 "$(printf '%s' "$P_TOOL" | bash "$WRAP" "$FAKE/nope.sh" >/dev/null 2>&1; echo $?)"
judge "stdout is always a single line" 1 "$(wrapf exit2.sh "$P_TOOL" | wc -l | tr -d ' ')"
judge "a .py hook runs under python3" "{}" "$(printf 'import sys\nsys.stdin.read()\nprint("{}")\n' > "$FAKE/h.py"; wrapf h.py "$P_TOOL")"
judge "CLAUDE_PLUGIN_ROOT is set to the extension root for the hook" "$ROOT" \
  "$(printf '#!/usr/bin/env bash\ncat >/dev/null\necho "$CLAUDE_PLUGIN_ROOT" >&2\necho "{}"\n' > "$FAKE/root.sh"; wrapf root.sh "$P_TOOL" >/dev/null; tr -d '\n' < "$TMP/err.txt")"

section "housekeeping"
judge "this test file is executable" yes "$(if [ -x "$ROOT/tests/test-gemini-hooks.sh" ]; then echo yes; else echo no; fi)"
judge "hooks/gemini-wrap.sh is executable" yes "$(if [ -x "$WRAP" ]; then echo yes; else echo no; fi)"
judge "scripts/build-gemini-hooks.sh is executable" yes "$(if [ -x "$GEN" ]; then echo yes; else echo no; fi)"
judge "no model name in the generated hooks file or the wrapper" "" \
  "$(grep -liE 'sonnet|opus|haiku|gemini-[0-9]|flash' "$HOOKS" "$WRAP" "$ROOT/hooks/lib/gemini-output.sh" 2>/dev/null || true)"

harness_summary
